const body = $json.body || $json;
const events = Array.isArray(body.events) ? body.events : [];
return events
  .filter((event) => event.source?.userId && ['follow', 'message'].includes(event.type))
  .filter((event) => event.type !== 'message' || event.message?.type === 'text')
  .map((event) => ({
    json: {
      eventType: event.type,
      lineUserId: event.source.userId,
      replyToken: event.replyToken,
      messageText: event.message?.text?.trim() || '',
      eventTimestamp: new Date(event.timestamp || Date.now()).toISOString()
    }
  }));

const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};

const now = new Date().toISOString();
const userId = item.lineUserId;
const text = (item.messageText || '').trim();
const lowerText = text.toLowerCase();
const restartKeywords = ['เริ่มใหม่', 'ลงทะเบียนใหม่', 'แก้ข้อมูล', 'กรอกใหม่'];
const isRestartKeyword = restartKeywords.some((keyword) => lowerText.includes(keyword.toLowerCase()));

let conversation = store.conversations[userId] || {
  state: 'idle',
  answers: {},
  createdAt: now,
  followedAt: item.eventType === 'follow' ? now : null,
  lineRef: null
};

conversation.displayName = item.displayName || conversation.displayName || null;
conversation.pictureUrl = item.pictureUrl || conversation.pictureUrl || null;
conversation.lastMessageAt = now;
if (item.eventType === 'follow' && !conversation.followedAt) conversation.followedAt = now;

const refMatch = text.match(/REF:([^\s]+)/i);
if (refMatch) conversation.lineRef = refMatch[1].slice(0, 255);

const questions = {
  waiting_parent_name: 'รบกวนขอชื่อคุณพ่อ/คุณแม่ หรือผู้ปกครองที่สะดวกให้ติดต่อกลับหน่อยค่ะ',
  waiting_phone: 'ขอเบอร์โทรที่สะดวกให้ทีมงานติดต่อกลับหน่อยนะคะ',
  waiting_student_name: 'น้องชื่ออะไรคะ จะได้ให้ทีมงานเรียกชื่อน้องถูกค่ะ 😊',
  waiting_student_grade: 'ตอนนี้น้องอยู่ระดับชั้นไหนคะ เช่น ป.4, ป.6 หรือ ม.1',
  waiting_pain_point: 'ตอนนี้อยากให้ eiMaths ช่วยน้องเรื่องไหนเป็นพิเศษคะ\nเช่น ไม่ชอบคณิต, กลัวเลข, ทำโจทย์ไม่ค่อยได้, เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ',
  waiting_preferred_contact_time: 'คุณพ่อ/คุณแม่สะดวกให้ทีมงานติดต่อกลับช่วงเวลาไหนคะ\nเช่น หลัง 18:00 หรือช่วงเย็นหลังเลิกงาน'
};

const welcomeText = 'สวัสดีค่ะ 😊 ขอบคุณที่สนใจทดลองเรียนฟรีกับ eiMaths นะคะ\nแอดมินขอข้อมูลนิดนึง เพื่อให้ทีมงานช่วยแนะนำคอร์สที่เหมาะกับน้องได้ค่ะ\n\n';
let shouldReply = true;
let replyText = '';
let completed = false;
let ignoredReason = null;

if (conversation.state === 'idle') {
  conversation.state = 'waiting_parent_name';
  conversation.answers = {};
  conversation.startedAt = now;
  replyText = welcomeText + questions.waiting_parent_name;
} else if (isRestartKeyword && ['completed', 'handover_to_staff'].includes(conversation.state)) {
  conversation.state = 'waiting_parent_name';
  conversation.answers = {};
  conversation.startedAt = now;
  replyText = welcomeText + questions.waiting_parent_name;
} else if (isRestartKeyword) {
  replyText = 'ตอนนี้กำลังอยู่ระหว่างลงทะเบียนนะคะ 😊\n' + (questions[conversation.state] || 'รบกวนตอบข้อมูลต่อได้เลยค่ะ');
} else if (conversation.state === 'waiting_parent_name') {
  conversation.answers.parent_name = text;
  conversation.state = 'waiting_phone';
  replyText = questions.waiting_phone;
} else if (conversation.state === 'waiting_phone') {
  const phone = text.replace(/[^0-9+]/g, '');
  if (!/^[0-9+]{8,15}$/.test(phone)) {
    replyText = 'เบอร์โทรอาจยังไม่ครบค่ะ\nรบกวนพิมพ์เป็นตัวเลขอีกครั้งนะคะ เช่น 0812345678';
  } else {
    conversation.answers.phone = phone;
    conversation.state = 'waiting_student_name';
    replyText = questions.waiting_student_name;
  }
} else if (conversation.state === 'waiting_student_name') {
  conversation.answers.student_name = text;
  conversation.state = 'waiting_student_grade';
  replyText = questions.waiting_student_grade;
} else if (conversation.state === 'waiting_student_grade') {
  conversation.answers.student_grade = text;
  conversation.state = 'waiting_pain_point';
  replyText = questions.waiting_pain_point;
} else if (conversation.state === 'waiting_pain_point') {
  conversation.answers.pain_point = text;
  conversation.state = 'waiting_preferred_contact_time';
  replyText = questions.waiting_preferred_contact_time;
} else if (conversation.state === 'waiting_preferred_contact_time') {
  conversation.answers.preferred_contact_time = text;
  conversation.state = 'completed';
  conversation.completedAt = now;
  completed = true;
  replyText = 'ขอบคุณมากค่ะ 😊\nระบบได้รับข้อมูลเรียบร้อยแล้วนะคะ\n\nทีมงาน eiMaths จะติดต่อกลับเพื่อนัดทดลองเรียนฟรี 2 คลาส และแนะนำแนวทางที่เหมาะกับน้องให้ค่ะ';
} else if (conversation.state === 'completed' || conversation.state === 'handover_to_staff') {
  shouldReply = false;
  ignoredReason = 'already_completed_handover_to_staff';
} else {
  shouldReply = false;
  ignoredReason = 'unknown_state_no_reply';
}

store.conversations[userId] = conversation;

let crmPayload = null;
if (completed) {
  const refParts = (conversation.lineRef || '').split('|');
  crmPayload = {
    ...conversation.answers,
    interest: 'ทดลองเรียนฟรี 2 คลาส',
    line_user_id: userId,
    line_display_name: conversation.displayName,
    line_picture_url: conversation.pictureUrl,
    line_follow_status: conversation.followedAt ? 'followed' : 'unknown',
    line_followed_at: conversation.followedAt,
    line_last_message_at: now,
    line_conversation_state: 'completed',
    line_ref: conversation.lineRef,
    line_source: 'new_customer_line_oa',
    utm_source: refParts[0] || 'line',
    utm_medium: refParts[1] || 'oa_chat',
    utm_campaign: refParts[2] || 'unknown',
    utm_content: refParts[3] || null,
    first_touch_source: refParts[0] || 'new_customer_line_oa',
    last_touch_source: 'new_customer_line_oa',
    created_from: 'new_customer_line_oa_chatbot',
    lead_status: 'new_lead'
  };

  conversation.state = 'handover_to_staff';
  conversation.handoverAt = now;
  store.conversations[userId] = conversation;
}

return [{
  json: {
    shouldReply,
    ignoredReason,
    completed,
    replyToken: item.replyToken,
    replyText,
    lineUserId: userId,
    conversationState: conversation.state,
    crmPayload
  }
}];

