={{ (() => {
  const lead = $('Conversation State').item.json.crmPayload || {};
  const crm = $json || {};
  const leadId = crm.id || crm.lead_id || crm.data?.id || crm.data?.lead_id || crm.data?.lead?.id || '';
  const baseUrl = ($env.EIMATHS_CRM_BASE_URL || 'https://test-web.eimaths-th.com').replace(/\/$/, '');
  const detailUrl = crm.lead_detail_url || (leadId ? `${baseUrl}/admin/crm/leads/${leadId}` : `${baseUrl}/admin/crm/leads`);
  const source = lead.utm_source || lead.line_source || 'line';
  const campaign = lead.utm_campaign || 'unknown';
  const content = lead.utm_content || '-';
  const lineName = lead.line_display_name || '-';
  const text = [
    '🔔 Lead ใหม่จาก New Customer LINE OA',
    '',
    `ผู้ปกครอง: ${lead.parent_name || '-'}`,
    `เบอร์: ${lead.phone || '-'}`,
    `LINE: ${lineName}`,
    `นักเรียน: ${lead.student_name || '-'}`,
    `ระดับชั้น: ${lead.student_grade || '-'}`,
    `ปัญหา: ${lead.pain_point || '-'}`,
    `สนใจ: ${lead.interest || 'ทดลองเรียนฟรี 2 คลาส'}`,
    `เวลาติดต่อ: ${lead.preferred_contact_time || '-'}`,
    '',
    `LINE source: ${lead.line_source || 'new_customer_line_oa'}`,
    `ช่องทางโฆษณา: ${source}`,
    `Campaign: ${campaign}`,
    `Content: ${content}`,
    `Created from: ${lead.created_from || 'new_customer_line_oa_chatbot'}`,
    `Action: ${crm.action || 'created'}`,
    '',
    `ดูรายละเอียด: ${detailUrl}`
  ].join('\n');

  return JSON.stringify({
    to: $env.LINE_MARKETING_GROUP_ID,
    messages: [{ type: 'text', text }]
  });
})() }}
